  getDayOfWeekBreakdown(filters={}) { const {rows,currency}=this.rowsForStats({...filters,type:'expense'}),by=new Map();for(const t of rows){const weekday=new Date(`${t.date}T12:00:00Z`).getUTCDay();if(!by.has(weekday))by.set(weekday,{weekday,total_minor:0,count:0});by.get(weekday).total_minor-=t.amount_minor;by.get(weekday).count++}return [...by.values()].map(v=>({...v,total:D.major(v.total_minor,currency)})).sort((a,b)=>a.weekday-b.weekday) }
  getAccounts() {return super.getAccounts().map(a=>({...a,balance:a.balance_minor===null?'':String(D.major(a.balance_minor,a.currency))}))}
  addAccount(account) { D.assert(typeof account.name==='string'&&account.name.trim(),'Account name required');D.precision(account.currency||'EUR');const row=super.addAccount({...account,balance:''});if(account.balance!==undefined&&account.balance!=='')this.setAccountBalance(row.id,account.balance,account.balance_date,account.balance_label);this.bump();return this.getAccounts().find(a=>a.id===row.id) }
